package net.minecraft.core;
import java.util.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.tags.TagKey;import net.minecraft.world.item.crafting.RecipeSerializer;
public final class Registry<T>{
 public final Map<ResourceLocation,Holder<T>> entries=new LinkedHashMap<>();private final Map<T,ResourceLocation> keys=new IdentityHashMap<>();public final Map<TagKey<T>,HolderSet.Named<T>> tags=new HashMap<>();
 public T get(ResourceLocation id){var holder=entries.get(id);return holder==null?null:holder.value();}
 public Holder<T> put(String id,T value){var holder=new Holder<T>(value);var key=ResourceLocation.parse(id);var old=entries.put(key,holder);if(old!=null)keys.remove(old.value());keys.put(value,key);return holder;}
 public ResourceLocation getKey(T value){var key=keys.get(value);if(key!=null)return key;return value instanceof RecipeSerializer<?> recipe?ResourceLocation.parse(recipe.id()):null;}
 public boolean containsKey(ResourceLocation id){return entries.containsKey(id);}
 public Optional<Holder<T>> getHolder(ResourceLocation id){return Optional.ofNullable(entries.get(id));}
 public Optional<HolderSet.Named<T>> getTag(TagKey<T> key){return Optional.ofNullable(tags.get(key));}
 public HolderSet.Named<T> bind(TagKey<T> key,List<Holder<T>> holders){var current=tags.computeIfAbsent(key,k->new HolderSet.Named<>(List.of()));current.bind(holders);return current;}
 public Holder<T> wrapAsHolder(T value){var key=getKey(value);if(key==null)throw new IllegalArgumentException("unregistered");return entries.get(key);}
}

